import os, re
from pathlib import Path

def grep_files(root, pattern, ext_filter=None):
    out, stack = [], [root]
    while stack:
        d = stack.pop()
        for name in sorted(os.listdir(d)):
            full = d + '/' + name
            if Path(full).is_dir():
                stack.append(full)
            elif ext_filter is None or full.endswith(ext_filter):
                try:
                    content = Path(full).read_text()
                    for i, line in enumerate(content.split('\n'), 1):
                        if re.search(pattern, line):
                            out.append((full, i, line.strip()))
                except Exception:
                    pass
    return out

